<?php
require_once __DIR__ . '/../../includes/functions.php';
requireLogin(); requireRole(['admin','superadmin']);
$user=currentUser(); $db=getDB(); $pageTitle='Medical Records'; $isDashboard=true;
$recordTypeColumn=$db->query("SHOW COLUMNS FROM pet_health_records LIKE 'record_type'")->fetch(PDO::FETCH_ASSOC);
if ($recordTypeColumn && str_starts_with(strtolower($recordTypeColumn['Type']), 'enum(')) $db->exec("ALTER TABLE pet_health_records MODIFY record_type VARCHAR(100) NOT NULL DEFAULT 'checkup'");
$prePet=(int)($_GET['pet'] ?? $_POST['pet_id'] ?? 0); $msg=''; $msgType='success'; $aiSummary=''; $aiError='';
$isSuper=$user['role_name']==='superadmin';
$petVisibility=$isSuper
    ? '(EXISTS (SELECT 1 FROM appointments a WHERE a.pet_id=p.id) OR EXISTS (SELECT 1 FROM pet_health_records hr WHERE hr.pet_id=p.id))'
    : '(EXISTS (SELECT 1 FROM appointments a JOIN clinics c ON c.id=a.clinic_id WHERE a.pet_id=p.id AND c.admin_id=?) OR EXISTS (SELECT 1 FROM pet_health_records hr JOIN veterinarians v ON v.id=hr.vet_id JOIN clinics c ON c.id=v.clinic_id WHERE hr.pet_id=p.id AND c.admin_id=?))';
$petScopeParams=$isSuper?[]:[$user['id'],$user['id']];
$petStmt=$db->prepare('SELECT p.* FROM pets p WHERE p.is_active=1 AND '.$petVisibility.' ORDER BY p.name'); $petStmt->execute($petScopeParams); $patients=$petStmt->fetchAll();
$recordClinics=$db->prepare('SELECT id,name FROM clinics'.($isSuper?'':' WHERE admin_id=?').' ORDER BY name'); $recordClinics->execute($isSuper?[]:[$user['id']]); $recordClinics=$recordClinics->fetchAll();
$petOwners=$db->query("SELECT u.id,u.first_name,u.last_name,u.email FROM users u JOIN roles r ON r.id=u.role_id WHERE r.name='pet_owner' AND u.is_active=1 ORDER BY u.last_name,u.first_name")->fetchAll();
$ownerPets=$db->query('SELECT p.id,p.owner_id,p.name,p.species,p.breed FROM pets p WHERE p.is_active=1 ORDER BY p.name')->fetchAll();
$canAccessPet = static function(int $petId) use ($db,$petVisibility,$petScopeParams): bool {
    $q=$db->prepare('SELECT 1 FROM pets p WHERE p.id=? AND p.is_active=1 AND '.$petVisibility.' LIMIT 1');
    $q->execute(array_merge([$petId],$petScopeParams)); return (bool)$q->fetchColumn();
};

if ($_SERVER['REQUEST_METHOD']==='POST') {
    if (!verifyCsrfToken($_POST['csrf_token'] ?? '')) { $msg='Invalid request.'; $msgType='danger'; }
    elseif (!isset($_POST['add_walkin_record']) && (!$prePet || !$canAccessPet($prePet))) { $msg='Pet not found in your clinic records.'; $msgType='danger'; }
    elseif (isset($_POST['add_walkin_record'])) {
        $ownerId=(int)($_POST['walkin_owner_id'] ?? 0); $petId=(int)($_POST['walkin_pet_id'] ?? 0); $clinicId=(int)($_POST['walkin_clinic_id'] ?? 0);
        $allowedClinic=false; foreach($recordClinics as $clinicRow) if((int)$clinicRow['id']===$clinicId) $allowedClinic=true;
        $ownerCheck=$db->prepare("SELECT u.id FROM users u JOIN roles r ON r.id=u.role_id WHERE u.id=? AND r.name='pet_owner' AND u.is_active=1"); $ownerCheck->execute([$ownerId]);
        $type=trim(sanitize($_POST['walkin_record_type'] ?? '')); $title=$type; $date=sanitize($_POST['walkin_record_date'] ?? '');
        if (!$allowedClinic || !$ownerCheck->fetchColumn()) { $msg='Choose an owner and a clinic you manage.'; $msgType='danger'; }
        elseif ($type==='' || strlen($type)>100 || !$date || (!$petId && trim($_POST['walkin_new_pet_name'] ?? '')==='')) { $msg='Choose an existing pet or enter a new pet name, and complete the record type and date.'; $msgType='danger'; }
        else {
            if ($petId) { $petCheck=$db->prepare('SELECT id FROM pets WHERE id=? AND owner_id=? AND is_active=1'); $petCheck->execute([$petId,$ownerId]); }
            else { $db->prepare('INSERT INTO pets (owner_id,name,species,breed,gender,age_years,age_months,weight_kg) VALUES (?,?,?,?,?,?,?,?)')->execute([$ownerId,sanitize($_POST['walkin_new_pet_name']),sanitize($_POST['walkin_species'] ?? 'Dog'),sanitize($_POST['walkin_breed'] ?? ''),in_array($_POST['walkin_gender'] ?? '',['male','female','unknown'],true)?$_POST['walkin_gender']:'unknown',(int)($_POST['walkin_age_years'] ?? 0),(int)($_POST['walkin_age_months'] ?? 0),(float)($_POST['walkin_weight'] ?? 0) ?: null]); $petId=(int)$db->lastInsertId(); $petCheck=$db->prepare('SELECT id FROM pets WHERE id=? AND owner_id=?'); $petCheck->execute([$petId,$ownerId]); }
            if (!$petCheck->fetchColumn()) { $msg='That pet does not belong to the selected owner.'; $msgType='danger'; }
            else { $vetQ=$db->prepare('SELECT id FROM veterinarians WHERE clinic_id=? ORDER BY id LIMIT 1'); $vetQ->execute([$clinicId]); $vetId=(int)$vetQ->fetchColumn(); if (!$vetId) { $msg='Add a veterinarian to this clinic before creating a walk-in medical record.'; $msgType='danger'; } else { $db->prepare('INSERT INTO pet_health_records (pet_id,vet_id,record_type,title,description,diagnosis,treatment,medications,next_appointment,record_date) VALUES (?,?,?,?,?,?,?,?,?,?)')->execute([$petId,$vetId,$type,sanitize($title),sanitize($_POST['walkin_notes'] ?? ''),sanitize($_POST['walkin_diagnosis'] ?? ''),sanitize($_POST['walkin_treatment'] ?? ''),null,sanitize($_POST['walkin_next_appointment'] ?? '') ?: null,$date]); $prePet=$petId; $msg='Walk-in patient medical record saved.'; } }
        }
    }
    elseif (isset($_POST['generate_summary'])) {
        if (!$canAccessPet($prePet)) { $aiError='This pet is not in your clinic records.'; }
        else {
            $petQ=$db->prepare('SELECT p.* FROM pets p WHERE p.id=?'); $petQ->execute([$prePet]); $pet=$petQ->fetch();
            $historyQ=$db->prepare('SELECT record_type,title,description,diagnosis,treatment,medications,record_date,next_appointment FROM pet_health_records WHERE pet_id=? ORDER BY record_date DESC'); $historyQ->execute([$prePet]); $history=$historyQ->fetchAll();
            $historyText=$history ? implode("\n",array_map(static fn($r)=>implode(' | ',array_filter([$r['record_date'].' '.$r['record_type'],$r['title'],$r['description'],$r['diagnosis'],$r['treatment'],$r['medications'],$r['next_appointment']?'Next appointment: '.$r['next_appointment']:''])), $history)) : 'No medical records are available yet.';
            $prompt="Summarize this pet's complete documented medical record history in a concise, neutral paragraph. Use only facts in the records, do not add diagnosis or treatment advice, and state if no history is recorded. This is a chart summary, not a diagnosis.\n\nPet: {$pet['name']}\nSpecies: {$pet['species']}\nBreed: {$pet['breed']}\nHistory:\n{$historyText}";
            $ai=callGroq($prompt,350);
            if ($ai['success']) { $aiSummary=trim($ai['text']); $db->prepare('INSERT INTO ai_summaries (pet_id,generated_by,summary,prompt_used) VALUES (?,?,?,?)')->execute([$prePet,$user['id'],$aiSummary,$prompt]); }
            else $aiError=$ai['text'];
        }
    }
    elseif (isset($_POST['add_record'])) {
        $type=sanitize($_POST['record_type'] ?? 'other'); $title=trim($_POST['title'] ?? ''); $date=sanitize($_POST['record_date'] ?? '');
        if ($type==='' || strlen($type)>100 || $title==='' || !$date) { $msg='Record type, title, and date are required.'; $msgType='danger'; }
        else {
            $staffQuery=$db->prepare('SELECT v.id FROM veterinarians v JOIN clinics c ON c.id=v.clinic_id'.($isSuper?'':' WHERE c.admin_id=?').' ORDER BY v.id LIMIT 1'); $staffQuery->execute($isSuper?[]:[$user['id']]); $recordVetId=(int)$staffQuery->fetchColumn();
            $db->prepare('INSERT INTO pet_health_records (pet_id,vet_id,record_type,title,description,diagnosis,treatment,medications,next_appointment,record_date) VALUES (?,?,?,?,?,?,?,?,?,?)')->execute([$prePet,$recordVetId ?: null,$type,sanitize($title),sanitize($_POST['description'] ?? ''),sanitize($_POST['diagnosis'] ?? ''),sanitize($_POST['treatment'] ?? ''),sanitize($_POST['medications'] ?? ''),sanitize($_POST['next_appointment'] ?? '') ?: null,$date]);
            $msg='Medical record added.';
        }
    } elseif (isset($_POST['update_record'])) {
        $id=(int)($_POST['record_id'] ?? 0); $type=sanitize($_POST['record_type'] ?? 'other'); $title=trim($_POST['title'] ?? ''); $date=sanitize($_POST['record_date'] ?? '');
        $verify=$db->prepare('SELECT 1 FROM pet_health_records WHERE id=? AND pet_id=?'); $verify->execute([$id,$prePet]);
        if (!$verify->fetchColumn()) { $msg='Medical record not found.'; $msgType='danger'; }
        elseif ($type==='' || strlen($type)>100 || $title==='' || !$date) { $msg='Record type, title, and date are required.'; $msgType='danger'; }
        else { $db->prepare('UPDATE pet_health_records SET record_type=?,title=?,description=?,diagnosis=?,treatment=?,medications=?,next_appointment=?,record_date=? WHERE id=? AND pet_id=?')->execute([$type,sanitize($title),sanitize($_POST['description'] ?? ''),sanitize($_POST['diagnosis'] ?? ''),sanitize($_POST['treatment'] ?? ''),sanitize($_POST['medications'] ?? ''),sanitize($_POST['next_appointment'] ?? '') ?: null,$date,$id,$prePet]); $msg='Medical record updated.'; }
    } elseif (isset($_POST['delete_record'])) {
        $id=(int)($_POST['record_id'] ?? 0); $db->prepare('DELETE FROM pet_health_records WHERE id=? AND pet_id=?')->execute([$id,$prePet]); $msg='Medical record deleted.';
    }
}

$selectedPet=null; $records=[];
if ($prePet && $canAccessPet($prePet)) {
    $q=$db->prepare('SELECT p.*,CONCAT(u.first_name," ",u.last_name) owner_name FROM pets p JOIN users u ON u.id=p.owner_id WHERE p.id=?'); $q->execute([$prePet]); $selectedPet=$q->fetch();
    if ($selectedPet) { $q=$db->prepare('SELECT * FROM pet_health_records WHERE pet_id=? ORDER BY record_date DESC,id DESC'); $q->execute([$prePet]); $records=$q->fetchAll(); }
}
?>
<?php include __DIR__.'/../../includes/header.php'; include __DIR__.'/../../includes/sidebar_admin.php'; ?>
<main class="dash-main"><div class="dash-header"><div style="display:flex;justify-content:space-between;align-items:center;gap:1rem;flex-wrap:wrap;"><div><h1>Medical Records</h1><p>Manage online appointment records and digitize walk-in visits.</p></div><button class="btn btn-primary" type="button" onclick="openModal('adminWalkinModal')"><i class="fas fa-user-plus"></i> Add Walk-in Record</button></div></div>
<?php if($msg): ?><div class="alert alert-<?= $msgType ?>" role="status"><?= sanitize($msg) ?></div><?php endif; ?><?php if($aiError): ?><div class="alert alert-danger" role="alert"><?= sanitize($aiError) ?></div><?php endif; ?>
<div class="dash-two-col" style="display:grid;grid-template-columns:250px 1fr;gap:1.25rem;align-items:start;">
<section class="card"><div class="card-header"><h3>Patients</h3></div><div style="padding:.5rem 0;">
<?php foreach($patients as $p): ?><a class="sidebar-link <?= $prePet===$p['id']?'active':'' ?>" href="records.php?pet=<?= (int)$p['id'] ?>"><i class="fas fa-paw"></i><span><?= sanitize($p['name']) ?></span></a><?php endforeach; ?>
<?php if(!$patients): ?><p style="padding:1rem;color:var(--text-muted)">No patients with clinic appointments yet.</p><?php endif; ?></div></section>
<div><?php if(!$selectedPet): ?><section class="card"><div class="card-body"><div class="empty-state"><i class="fas fa-file-medical"></i><h3>Select a patient</h3><p>Choose a pet to view and manage its medical history.</p></div></div></section><?php else: ?>
<section class="card" style="margin-bottom:1rem;"><div class="card-body"><h2><?= sanitize($selectedPet['name']) ?>’s medical records</h2><p style="color:var(--text-muted)"><?= sanitize($selectedPet['species']) ?> · Owner: <?= sanitize($selectedPet['owner_name']) ?></p><form method="POST" style="margin:.75rem 0;"><?= csrfField() ?><input type="hidden" name="pet_id" value="<?= (int)$selectedPet['id'] ?>"><button class="btn btn-secondary" name="generate_summary" value="1"><i class="fas fa-robot"></i> AI Summarize History</button></form><?php if($aiSummary): ?><div class="alert alert-info"><strong>AI medical history summary</strong><p><?= nl2br(sanitize($aiSummary)) ?></p><small>AI-generated; verify against the source records.</small></div><?php endif; ?>
<div class="form-row"><div class="form-group"><label class="form-label">Pet</label><input class="form-control" value="<?= sanitize($selectedPet['name']) ?>" readonly></div><div class="form-group"><label class="form-label">Owner</label><input class="form-control" value="<?= sanitize($selectedPet['owner_name']) ?>" readonly></div></div><form method="POST" style="margin-top:1rem;"><?= csrfField() ?><input type="hidden" name="pet_id" value="<?= (int)$selectedPet['id'] ?>"><input type="hidden" name="add_record" value="1"><div class="form-row"><div class="form-group"><label class="form-label">Type</label><input name="record_type" class="form-control" value="" required maxlength="100" placeholder="Record type, e.g. Vaccination"></div><div class="form-group"><label class="form-label">Date</label><input type="date" name="record_date" class="form-control" value="<?= date('Y-m-d') ?>" required></div><div class="form-group"><label class="form-label">Title</label><input name="title" class="form-control" required></div></div><div class="form-row"><div class="form-group"><label class="form-label">Description</label><textarea name="description" class="form-control"></textarea></div><div class="form-group"><label class="form-label">Diagnosis</label><textarea name="diagnosis" class="form-control"></textarea></div><div class="form-group"><label class="form-label">Treatment</label><textarea name="treatment" class="form-control"></textarea></div></div><div class="form-row"><div class="form-group"><label class="form-label">Medications</label><textarea name="medications" class="form-control"></textarea></div><div class="form-group"><label class="form-label">Next appointment</label><input type="date" name="next_appointment" class="form-control"></div></div><button class="btn btn-primary">Add Record</button></form></div></section>
<section class="card"><div class="card-header"><h3>History (<?= count($records) ?>)</h3></div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Type</th><th>Title</th><th>Details / Manage</th></tr></thead><tbody>
<?php foreach($records as $r): ?><tr><td><?= date('M j, Y',strtotime($r['record_date'])) ?></td><td><?= sanitize(ucfirst($r['record_type'])) ?></td><td><?= sanitize($r['title']) ?></td><td><details><summary class="btn btn-sm btn-outline">Edit</summary><form method="POST" style="min-width:240px;padding:.5rem;"><?= csrfField() ?><input type="hidden" name="pet_id" value="<?= (int)$selectedPet['id'] ?>"><input type="hidden" name="record_id" value="<?= (int)$r['id'] ?>"><input type="hidden" name="update_record" value="1"><input name="record_type" class="form-control" value="<?= sanitize($r['record_type']) ?>" required maxlength="100"><input type="date" name="record_date" class="form-control" value="<?= sanitize($r['record_date']) ?>" required><input name="title" class="form-control" value="<?= sanitize($r['title']) ?>" required><textarea name="description" class="form-control" placeholder="Description"><?= sanitize($r['description'] ?? '') ?></textarea><textarea name="diagnosis" class="form-control" placeholder="Diagnosis"><?= sanitize($r['diagnosis'] ?? '') ?></textarea><textarea name="treatment" class="form-control" placeholder="Treatment"><?= sanitize($r['treatment'] ?? '') ?></textarea><textarea name="medications" class="form-control" placeholder="Medications"><?= sanitize($r['medications'] ?? '') ?></textarea><input type="date" name="next_appointment" class="form-control" value="<?= sanitize($r['next_appointment'] ?? '') ?>"><button class="btn btn-primary btn-sm">Save</button></form><form method="POST" onsubmit="return confirm('Delete this record?')"><?= csrfField() ?><input type="hidden" name="pet_id" value="<?= (int)$selectedPet['id'] ?>"><input type="hidden" name="record_id" value="<?= (int)$r['id'] ?>"><button name="delete_record" value="1" class="btn btn-danger btn-sm">Delete</button></form></details></td></tr><?php endforeach; ?>
<?php if(!$records): ?><tr><td colspan="4">No medical records yet.</td></tr><?php endif; ?></tbody></table></div></section>
<?php endif; ?></div></div>
<div class="modal-overlay" id="adminWalkinModal"><div class="modal" style="max-width:720px;"><div class="modal-header"><h3>New Walk-in Medical Record</h3><button class="modal-close" onclick="closeModal('adminWalkinModal')"><i class="fas fa-times"></i></button></div><div class="modal-body"><form method="POST"><?= csrfField() ?><input type="hidden" name="add_walkin_record" value="1"><div class="form-row"><div class="form-group"><label class="form-label">Clinic</label><select name="walkin_clinic_id" class="form-control" required><option value="">Choose clinic</option><?php foreach($recordClinics as $c): ?><option value="<?= (int)$c['id'] ?>"><?= sanitize($c['name']) ?></option><?php endforeach; ?></select></div><div class="form-group"><label class="form-label">Pet owner</label><select name="walkin_owner_id" id="adminWalkinOwner" class="form-control" required onchange="filterAdminWalkinPets()"><option value="">Choose owner</option><?php foreach($petOwners as $o): ?><option value="<?= (int)$o['id'] ?>"><?= sanitize($o['first_name'].' '.$o['last_name'].' ('.$o['email'].')') ?></option><?php endforeach; ?></select></div></div><div class="form-group"><label class="form-label">Existing pet</label><select name="walkin_pet_id" id="adminWalkinPet" class="form-control" onchange="toggleAdminNewPet()"><option value="">— Create a new pet profile —</option><?php foreach($ownerPets as $p): ?><option value="<?= (int)$p['id'] ?>" data-owner="<?= (int)$p['owner_id'] ?>" hidden><?= sanitize($p['name'].' — '.($p['breed'] ?: $p['species'])) ?></option><?php endforeach; ?></select></div><div id="adminNewPetFields" class="card" style="padding:1rem;margin-bottom:1rem;"><h4>New pet profile</h4><div class="form-row"><div class="form-group"><label class="form-label">Pet name</label><input name="walkin_new_pet_name" id="adminNewPetName" class="form-control"></div><div class="form-group"><label class="form-label">Species</label><input name="walkin_species" class="form-control" value="Dog"></div><div class="form-group"><label class="form-label">Breed</label><input name="walkin_breed" class="form-control"></div></div><div class="form-row"><div class="form-group"><label class="form-label">Gender</label><select name="walkin_gender" class="form-control"><option value="unknown">Unknown</option><option value="female">Female</option><option value="male">Male</option></select></div><div class="form-group"><label class="form-label">Age years</label><input type="number" min="0" name="walkin_age_years" class="form-control"></div><div class="form-group"><label class="form-label">Age months</label><input type="number" min="0" max="11" name="walkin_age_months" class="form-control"></div><div class="form-group"><label class="form-label">Weight kg</label><input type="number" min="0" step="0.01" name="walkin_weight" class="form-control"></div></div></div><div class="form-row"><div class="form-group"><label class="form-label">Record type</label><input type="text" name="walkin_record_type" class="form-control" placeholder="e.g. Vaccination, wellness exam" maxlength="100" required></div><div class="form-group"><label class="form-label">Record date</label><input type="date" name="walkin_record_date" class="form-control" value="<?= date('Y-m-d') ?>" required></div></div><div class="form-row"><div class="form-group"><label class="form-label">Notes</label><textarea name="walkin_notes" class="form-control"></textarea></div><div class="form-group"><label class="form-label">Diagnosis</label><textarea name="walkin_diagnosis" class="form-control"></textarea></div></div><div class="form-row"><div class="form-group"><label class="form-label">Treatment</label><textarea name="walkin_treatment" class="form-control"></textarea></div></div><div class="form-group"><label class="form-label">Next appointment</label><input type="date" name="walkin_next_appointment" class="form-control"></div><div class="modal-footer"><button type="button" class="btn btn-outline" onclick="closeModal('adminWalkinModal')">Cancel</button><button class="btn btn-primary">Save Walk-in Record</button></div></form></div></div></div>
</main><script>
function filterAdminWalkinPets(){const owner=document.getElementById('adminWalkinOwner').value,select=document.getElementById('adminWalkinPet');Array.from(select.options).forEach((o,i)=>{if(!i)return;const show=!!owner&&o.dataset.owner===owner;o.hidden=!show;if(!show&&o.selected)select.value='';});toggleAdminNewPet();}
function toggleAdminNewPet(){const fresh=!document.getElementById('adminWalkinPet').value;document.getElementById('adminNewPetFields').style.display=fresh?'block':'none';document.getElementById('adminNewPetName').required=fresh;}
</script>
